contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 amount) public payable {
        require(user != address(0), "zero user");
        require(amount > 0, "zero amount");
        require(user != address(c), "user is c");

        uint256 totalSupplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(user);

        uint256 minted = amount * 2 + 1_000_000;
        (bool okMint, bytes memory mintRet) = address(c.stakingToken()).call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), minted)
        );
        require(okMint, "mint failed");
        if (mintRet.length > 0) {
            require(abi.decode(mintRet, (bool)), "mint reverted");
        }

        (bool okApprove, bytes memory approveRet) = address(c.stakingToken()).call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), minted)
        );
        require(okApprove, "approve failed");
        if (approveRet.length > 0) {
            require(abi.decode(approveRet, (bool)), "approve reverted");
        }

        bool stakeReverted;
        try c.stakeFor(user, amount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        uint256 totalSupplyAfterStake = c.totalSupply();
        uint256 balanceAfterStake = c.balanceOf(user);

        bool withdrawReverted;
        if (!stakeReverted) {
            try c.withdraw(amount, false) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        uint256 totalSupplyAfterWithdraw = c.totalSupply();
        uint256 balanceAfterWithdraw = c.balanceOf(user);

        assert(
            !stakeReverted &&
            totalSupplyAfterStake == totalSupplyBefore + amount &&
            balanceAfterStake == balanceBefore + amount &&
            !withdrawReverted &&
            totalSupplyAfterWithdraw == totalSupplyBefore &&
            balanceAfterWithdraw == balanceBefore
        );
    }

    receive() external payable {}
}

