contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount1, uint256 amount2, bool claim) public {
        // Record the initial total supply (should be 0 for a fresh deployment).
        uint256 initialSupply = c.totalSupply();

        // Precondition: amounts are positive and small enough to avoid overflow in the sum.
        require(amount1 > 0, "amount1 must be > 0");
        require(amount2 > 0, "amount2 must be > 0");
        require(amount1 + amount2 > amount1, "overflow");

        // Stake amount1.
        c.stake(amount1);

        // Stake amount2.
        c.stake(amount2);

        // The total supply should now be initialSupply + amount1 + amount2.
        uint256 supplyAfterStakes = c.totalSupply();
        require(supplyAfterStakes == initialSupply + amount1 + amount2, "supply after stakes");

        // Withdraw amount1 (claiming or not according to the boolean parameter).
        c.withdraw(amount1, claim);

        // Final total supply should be initialSupply + amount2.
        uint256 finalSupply = c.totalSupply();

        // The contract must hold at least the total staked amount as staking tokens.
        // Since the staking token is arbitrary, we can only compare its balance if we
        // know it; but we can at least assert the total supply arithmetic invariant.
        assert(finalSupply == initialSupply + amount2);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount1, uint256 amount2, bool claim) public {
        uint256 initialSupply = c.totalSupply();

        require(amount1 > 0, "amount1 > 0");
        require(amount2 > 0, "amount2 > 0");
        require(amount1 <= type(uint256).max - initialSupply, "overflow1");
        require(amount2 <= type(uint256).max - initialSupply - amount1, "overflow2");

        c.stake(amount1);
        c.stake(amount2);

        uint256 supplyAfterStakes = c.totalSupply();
        require(supplyAfterStakes == initialSupply + amount1 + amount2, "supply after stakes");

        c.withdraw(amount1, claim);

        uint256 finalSupply = c.totalSupply();
        uint256 expectedFinal = initialSupply + amount2;

        assert(finalSupply == expectedFinal);
    }
}

