    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        require(stakeAmount > 0);
        require(withdrawAmount > 0);

        uint256 beforeBal = c.balanceOf(address(this));
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        try c.withdraw(withdrawAmount, false) {
            reverted = false;
