contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0 && amount < type(uint128).max, "amount out of safe range");

        uint256 totalBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        // Provide the staking tokens to the test contract so it can call stakeFor.
        // We acquire them from c? No - c holds staking tokens; we cannot mint.
        // Instead we rely on the test contract already having staking tokens?
        // For this property to be reachable, the test contract must hold amount of the staking token.
        // The staking token is some external IERC20; we cannot mint. We can't guarantee balance.
        // However the property should hold whenever the call does not revert.
        // We attempt the call and condition the assertion on success.
        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));

        // If the stake succeeded, totalSupply and the staker's balance must each have grown by exactly amount.
        assert(reverted || (totalAfter == totalBefore + amount && balanceAfter == balanceBefore + amount));
    }

    receive() external payable {}
}

