contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public payable {
        require(token != address(0), "zero token");

        uint256 beforeLen = c.rewardTokens(0) == address(0) && c.rewardTokens.length == 0 ? 0 : c.rewardTokens.length;
        uint256 beforeIndexLen = _rewardTokensLength();
        uint40 beforeLastUpdateTime = c.rewardPeriodFinish(token);
        uint256 beforeClaimable = c.claimableRewards(address(this), token);

        bool firstReverted;
        try c.addReward(token) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 afterFirstLen = _rewardTokensLength();

        if (beforeLastUpdateTime == 0) {
            assert(!firstReverted);
            assert(afterFirstLen == beforeIndexLen + 1);
            assert(c.rewardPeriodFinish(token) != 0);
            assert(c.claimableRewards(address(this), token) == beforeClaimable);

            bool secondReverted;
            try c.addReward(token) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }

            assert(secondReverted);
            assert(_rewardTokensLength() == afterFirstLen);
        } else {
            assert(firstReverted);
            assert(afterFirstLen == beforeIndexLen);
            assert(c.rewardPeriodFinish(token) == beforeLastUpdateTime);
        }
    }

    function _rewardTokensLength() private view returns (uint256 len) {
        while (true) {
            try c.rewardTokens(len) returns (address) {
                len++;
            } catch {
                break;
            }
        }
    }

    receive() external payable {}
}

