    function run(address rewardToken, uint256 amount, address owner) public {
        // Arrange: make the test contract the owner so it can add rewards and set the distributor.
        // c.owner() is a public view function from Ownable.
        require(c.owner() == address(this), "test must be owner");

        c.addReward(rewardToken);
        c.setRewardDistributor(address(this));

        uint256 supplyBefore = c.totalSupply();
        uint256 rateBefore = c.rewardData(rewardToken).rewardRate;

        uint256 amountToNotify = amount == 0 ? 1 : amount;

        c.notifyRewardAmount(rewardToken, amountToNotify);

        uint256 supplyAfter = c.totalSupply();
        uint256 rateAfter = c.rewardData(rewardToken).rewardRate;

        // General rule: notifying rewards does not change totalSupply and
        // sets rewardRate to the notified amount divided by DURATION.
        assert(supplyAfter == supplyBefore && rateAfter == amountToNotify / c.DURATION());
    }

    receive() external payable {}
}

