contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0);

        address stakingTokenAddr = address(c.stakingToken());

        // Give this test contract enough stake tokens and approve c to spend them.
        (bool minted, ) = stakingTokenAddr.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), amount)
        );
        require(minted, "mint failed");

        (bool approved, ) = stakingTokenAddr.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), amount)
        );
        require(approved, "approve failed");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        c.stake(amount);

        uint256 balanceAfterStake = c.balanceOf(address(this));
        uint256 supplyAfterStake = c.totalSupply();

        // A stake must increase the caller's balance by exactly the staked amount,
        // and must increase total supply by exactly the staked amount.
        assert(
            balanceAfterStake == balanceBefore + amount &&
            supplyAfterStake == supplyBefore + amount &&
            c.balanceOf(address(this)) <= c.totalSupply()
        );

        c.withdraw(amount, false);

        uint256 balanceAfterWithdraw = c.balanceOf(address(this));
        uint256 supplyAfterWithdraw = c.totalSupply();

        // The account's balance and the total supply must be restored exactly.
        assert(
            balanceAfterWithdraw == balanceBefore &&
            supplyAfterWithdraw == supplyBefore
        );
    }
}

