        c.stake(amount);

        // Read observable post-state.
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 contractBalanceAfter = stakingToken.balanceOf(address(c));

        // General rule: a successful stake increases the caller's balance and
        // total supply by exactly the staked amount, and moves exactly that
        // amount of the staking token into c.
        assert(
            totalAfter == totalBefore + amount &&
            balAfter == balBefore + amount &&
            contractBalanceAfter == contractBalanceBefore + amount
        );
    }

