contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 rewardAmount) public {
        require(rewardToken != address(0), "zero reward token");
        require(rewardAmount > 0, "zero reward amount");

        // Make the test contract the distributor so notifyRewardAmount can be called.
        c.setRewardDistributor(address(this));

        // Register the reward token. For a freshly deployed c this must succeed.
        c.addReward(rewardToken);

        // Fund this contract with reward tokens. A minimal ERC20-like transfer is
        // expected to be available on rewardToken.
        (bool fundingSuccess, ) = rewardToken.call(
            abi.encodeWithSignature("transfer(address,uint256)", address(this), rewardAmount)
        );
        require(fundingSuccess, "funding failed");

        // Approve c to pull rewardAmount of rewardToken from this contract.
        (bool approveSuccess, ) = rewardToken.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), rewardAmount)
        );
        require(approveSuccess, "approval failed");

        uint40 periodFinishBefore = c.rewardPeriodFinish(rewardToken);

        // The deciding call: notify a reward amount for a known reward token.
        c.notifyRewardAmount(rewardToken, rewardAmount);

        uint40 periodFinishAfter = c.rewardPeriodFinish(rewardToken);

        // General rule: a notification extends the period to now + DURATION.
        // Expressed additively to avoid subtraction underflow.
        assert(uint256(periodFinishAfter) == block.timestamp + 7 * 86400);
        assert(uint256(periodFinishAfter) > uint256(periodFinishBefore));
    }

    receive() external payable {}
}

