contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount, address rewardAccount) public {
        require(stakeAmount > 0);

        uint256 cBalBefore = c.stakingToken().balanceOf(address(c));
        uint256 totalBefore = c.totalSupply();
        bool invariantBefore = cBalBefore >= totalBefore;

        c.stake(stakeAmount);

        uint256 cBalAfter = c.stakingToken().balanceOf(address(c));
        uint256 totalAfter = c.totalSupply();

        bool stakeHeld = cBalAfter == cBalBefore + stakeAmount;
        bool totalGrew = totalAfter == totalBefore + stakeAmount;
        bool stakeInvariant = cBalAfter >= totalAfter;

        uint256 balOfTest = c.balanceOf(address(this));
        if (balOfTest > 0 && withdrawAmount > 0) {
            uint256 amount = (withdrawAmount % balOfTest) + 1;
            uint256 cBalBeforeWithdraw = c.stakingToken().balanceOf(address(c));
            uint256 totalBeforeWithdraw = c.totalSupply();
            c.withdraw(amount, false);
            uint256 cBalAfterWithdraw = c.stakingToken().balanceOf(address(c));
            uint256 totalAfterWithdraw = c.totalSupply();
            bool withdrawHeld = cBalAfterWithdraw == cBalBeforeWithdraw - amount;
            bool totalShrank = totalAfterWithdraw == totalBeforeWithdraw - amount;
            bool withdrawInvariant = cBalAfterWithdraw >= totalAfterWithdraw;
            assert(
                invariantBefore &&
                stakeHeld &&
                totalGrew &&
                stakeInvariant &&
                withdrawHeld &&
                totalShrank &&
                withdrawInvariant
            );
        } else {
            assert(
                invariantBefore &&
                stakeHeld &&
                totalGrew &&
                stakeInvariant
            );
        }
    }

    receive() external payable {}
}

