contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address rewToken, uint256 amount, address distributor) public payable {
        // Set up the distributor and register the reward token.
        c.setRewardDistributor(distributor);
        require(address(this) != address(c), "bad");
        // If distributor is the test contract, reward transferFrom will pull from us.
        require(rewToken != address(0), "bad token");
        c.addReward(rewToken);

        uint40 beforeFinish = c.rewardPeriodFinish(rewToken);
        uint256 balBefore = IERC20(rewToken).balanceOf(address(c));

        bool reverted;
        if (amount > 0 && msg.sender == distributor) {
            c.notifyRewardAmount(rewToken, amount);
            reverted = false;
        } else {
            // Not the distributor or zero amount: expect revert, otherwise rule holds aside.
            try c.notifyRewardAmount(rewToken, amount) { reverted = false; } catch { reverted = true; }
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewToken);
        uint256 balAfter = IERC20(rewToken).balanceOf(address(c));

        if (!reverted) {
            assert(afterFinish > beforeFinish && balAfter >= balBefore);
        } else {
            assert(afterFinish == beforeFinish);
        }
    }

    receive() external payable {}
}

